export interface CrawlingoErrorOptions extends ErrorOptions {
  code?: string;
  url?: string;
  stage?: string;
  recoverable?: boolean;
  suggestion?: string;
  seconds?: number;
  host?: string;
}

export interface JobConfig {
  urls_file: string;
  output_dir: string;
  fields: JobField[];
  row_selector?: string;
  concurrency?: number;
  checkpoint_pages?: number;
  checkpoint_bytes?: number;
  max_response_bytes?: number;
  max_records_per_page?: number;
  max_record_bytes?: number;
  deduplicate?: boolean;
  dedup_fields?: string[];
  respect_robots?: boolean;
  format?: 'jsonl' | 'csv';
}

export interface JobField {
  name: string;
  selector: string;
  selector_type?: 'css' | 'xpath' | 'regex' | 'text' | 'after_text' | 'before_text';
  extract_type?: 'text' | 'price' | 'datetime' | 'url' | `attr:${string}`;
  required?: boolean;
  default?: string;
  data_type?: 'string' | 'integer' | 'float' | 'boolean';
  normalize_whitespace?: boolean;
  min_length?: number;
}

export interface JobReport {
  source_lines: number;
  pages_fetched: number;
  pages_failed: number;
  duplicate_urls: number;
  records_written: number;
  records_rejected: number;
  duplicate_records: number;
  shards: number;
  complete: boolean;
  cancelled: boolean;
  elapsed_ms: number;
}

export interface WatchChangeEvent {
  url: string;
  field: string;
  changeType: string;
  oldValue?: string;
  newValue?: string;
}

export interface SitemapEntry {
  loc: string;
  lastmod?: string;
  changefreq?: string;
  priority?: string;
}

export interface DownloadResult {
  /** The final URL after any redirects. */
  url: string;
  /** HTTP response status code. */
  status: number;
  /** Number of bytes written to the output. */
  bytesWritten: number;
  /** MIME type from `Content-Type`, or `application/octet-stream`. */
  contentType: string;
  /** Filename hint from `Content-Disposition` or the URL's last path segment. */
  suggestedFilename?: string;
  /** `true` if the server honored a `Range:` request and returned `206`. */
  resumed: boolean;
}

export enum FieldType {
  String = 0,
  Integer = 1,
  Float = 2,
  Boolean = 3,
}
